namespace Payments;

public sealed class SettlementBatchProcessor
{
    public SettlementResult Process(string merchantId, IEnumerable<PaymentItem> items, string settlementCurrency,
        decimal percentageFee, decimal fixedFee, decimal submissionLimit, ISettlementGateway gateway)
    {
        var lines = new List<SettlementLine>();
        var accepted = new List<(string Reference, decimal Net)>();

        CollectAcceptedItems(items, settlementCurrency, percentageFee, fixedFee, submissionLimit, lines, accepted);

        return CompleteSettlement(merchantId, settlementCurrency, gateway, lines, accepted);
    }

    private static void CollectAcceptedItems(
        IEnumerable<PaymentItem> items,
        string settlementCurrency,
        decimal percentageFee,
        decimal fixedFee,
        decimal submissionLimit,
        List<SettlementLine> lines,
        List<(string Reference, decimal Net)> accepted)
    {
        var seen = new HashSet<string>(StringComparer.Ordinal);

        foreach (var item in items)
        {
            if (TryGetEligibilityRejection(item, settlementCurrency, seen, out var rejection))
            {
                lines.Add(new SettlementLine(item.Reference, 0m, rejection));
                continue;
            }

            var net = CalculateNet(item.GrossAmount, percentageFee, fixedFee);
            if (net <= 0m)
            {
                lines.Add(new SettlementLine(item.Reference, 0m, "fee-exceeds-amount"));
                continue;
            }

            if (accepted.Sum(entry => entry.Net) + net > submissionLimit)
            {
                lines.Add(new SettlementLine(item.Reference, 0m, "batch-limit"));
                continue;
            }

            accepted.Add((item.Reference, net));
        }
    }

    private static bool TryGetEligibilityRejection(
        PaymentItem item,
        string settlementCurrency,
        HashSet<string> seen,
        out string rejection)
    {
        if (string.IsNullOrWhiteSpace(item.Reference))
        {
            rejection = "invalid-reference";
            return true;
        }

        if (!seen.Add(item.Reference))
        {
            rejection = "duplicate";
            return true;
        }

        if (!string.Equals(item.Currency, settlementCurrency, StringComparison.OrdinalIgnoreCase))
        {
            rejection = "currency-mismatch";
            return true;
        }

        if (item.GrossAmount <= 0m)
        {
            rejection = "invalid-amount";
            return true;
        }

        if (item.Refunded)
        {
            rejection = "refunded";
            return true;
        }

        if (item.Held)
        {
            rejection = "held";
            return true;
        }

        rejection = string.Empty;
        return false;
    }

    private static decimal CalculateNet(decimal grossAmount, decimal percentageFee, decimal fixedFee)
    {
        var fee = decimal.Round(grossAmount * percentageFee + fixedFee, 2);
        return decimal.Round(grossAmount - fee, 2);
    }

    private static SettlementResult CompleteSettlement(
        string merchantId,
        string settlementCurrency,
        ISettlementGateway gateway,
        List<SettlementLine> lines,
        List<(string Reference, decimal Net)> accepted)
    {
        if (accepted.Count == 0)
            return new SettlementResult(lines, 0m, "empty");

        if (string.IsNullOrWhiteSpace(merchantId))
        {
            return new SettlementResult(
                [.. lines, .. accepted.Select(entry => new SettlementLine(entry.Reference, 0m, "invalid-merchant"))],
                0m,
                "rejected");
        }

        var total = accepted.Sum(entry => entry.Net);
        var references = accepted.Select(entry => entry.Reference).ToArray();
        var gatewayResult = gateway.Submit(merchantId, settlementCurrency, total, references);

        if (!gatewayResult.Accepted)
        {
            return new SettlementResult(
                [.. lines, .. accepted.Select(entry => new SettlementLine(entry.Reference, 0m, $"gateway-{gatewayResult.Code}"))],
                0m,
                "rejected");
        }

        lines.AddRange(accepted.Select(entry => new SettlementLine(entry.Reference, entry.Net, "submitted")));
        return new SettlementResult(lines, total, lines.Any(line => line.Status != "submitted") ? "partial" : "submitted");
    }
}
